-- Olivia O'Brien (profileID=15) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Olivia O'Brien phrasings

SELECT p.argumentID, p.phrasingID, 15, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 15
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 15 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=15 AND targArgID IN (67,68,80,100,101,103,106,107,110,145,148,153,154,175,182,184,193,200,217,219,242,288,293,295,320,355,356,359,360,361,362,363,364,365,367,368,374,378,413,416,463,484,485,500,504,539,546,547,560,578,579,580,590,603,636,654,696,697,698,745,748,756,894,895,896,897,898,909,910,958);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 15
SET pe.active = o.acceptance
WHERE pe.profileID = 15;

SELECT 'Done: endorsements for profileID=15' AS status;